final List<String> kVietnamProvinces =
    List<String>.unmodifiable(kVnProvinces.map((p) => p.name));

final Map<String, List<String>> kVietnamWardsByProvince =
    Map<String, List<String>>.unmodifiable({
  for (final p in kVnProvinces)
    p.name: List<String>.unmodifiable(p.wards.map((w) => w.name)),
});

/// Resolve tên tỉnh linh hoạt ("Hà Nội" ↔ "Thành phố Hà Nội").
String? vnMatchProvinceName(String? raw) {
  final q = (raw ?? "").trim();
  if (q.isEmpty) return null;
  for (final p in kVnProvinces) {
    if (p.name == q) return p.name;
  }
  final lower = q.toLowerCase();
  for (final p in kVnProvinces) {
    final n = p.name.toLowerCase();
    if (n.endsWith(lower) || n.contains(lower) || lower.contains(n)) return p.name;
  }
  final stripped = lower
      .replaceAll("thành phố ", "")
      .replaceAll("tinh ", "")
      .replaceAll("tỉnh ", "")
      .trim();
  for (final p in kVnProvinces) {
    final n = p.name.toLowerCase()
        .replaceAll("thành phố ", "")
        .replaceAll("tinh ", "")
        .replaceAll("tỉnh ", "")
        .trim();
    if (n == stripped || n.contains(stripped) || stripped.contains(n)) return p.name;
  }
  return null;
}

List<String> vnWardsForProvince(String? province) {
  final key = vnMatchProvinceName(province);
  if (key == null) return const [];
  return kVietnamWardsByProvince[key] ?? const [];
}

String? vnMatchWardName(String? province, String? ward) {
  final q = (ward ?? "").trim();
  if (q.isEmpty) return null;
  final wards = vnWardsForProvince(province);
  for (final w in wards) {
    if (w == q) return w;
  }
  final lower = q.toLowerCase();
  for (final w in wards) {
    if (w.toLowerCase() == lower || w.toLowerCase().contains(lower) || lower.contains(w.toLowerCase())) {
      return w;
    }
  }
  return null;
}

